# complexity: O(N + Q)
def f(N, edges, Q, K, queries):
    '''
    N: an integer
    edges: a list of tuples, each containing three integers
    Q: an integer
    K: an integer
    queries: a list of tuples, each containing two integers
    '''
    ans = 0
    visited = set()
    queue = []
    for (u, v, w) in edges:
        if u == K or v == K:
            ans += w
        else:
            if u not in visited:
                visited.add(u)
                queue.append(u)
            if v not in visited:
                visited.add(v)
                queue.append(v)
    while queue:
        node = queue.pop(0)
        for (u, v, w) in edges:
            if node == u:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
            elif node == v:
                if u not in visited:
                    visited.add(u)
                    queue.append(u)
    for (u, v) in queries:
        if u not in visited or v not in visited:
            continue
        else:
            ans += 1
    return ans
